_G.LobbySkinInjector = _G.LobbySkinInjector or {
    applied = false,
    customSet = nil,
    fakeByRes = {},
    customWorn = {},
    BASE_ID = 900000000,
    MAX_CUSTOM_IN_LIST = 3000
}

local LSI = _G.LobbySkinInjector

local function fakeInstanceId(resId)
    resId = tonumber(resId)
    if not resId or resId == 0 then return LSI.BASE_ID end
    if LSI.fakeByRes[resId] then return LSI.fakeByRes[resId] end
    local fakeId = LSI.BASE_ID + resId
    LSI.fakeByRes[resId] = fakeId
    return fakeId
end

local function isCustomItem(resId)
    if not resId or resId == 0 then return false end
    resId = tonumber(resId)
    if LSI.customSet then return LSI.customSet[resId] == true end
    for _, id in ipairs(CUSTOM_ITEM_IDS) do 
        if id == resId then return true end 
    end
    return false
end

local function isFakeInstance(insId)
    insId = tonumber(insId)
    if not insId or insId < LSI.BASE_ID then return false end
    local realId = insId - LSI.BASE_ID
    return isCustomItem(realId) and realId or false
end

local function getItemConfig(resId)
    if not CDataTable or not resId then return nil end
    local ok, cfg = pcall(CDataTable.GetTableData, "item", resId)
    if ok and cfg then return cfg end
    ok, cfg = pcall(CDataTable.GetTableData, "Item", resId)
    return (ok and cfg) or nil
end

local function getItemTabs(resId)
    local cfg = getItemConfig(resId)
    if cfg and cfg.WardrobeMainTab ~= nil and cfg.WardrobeTab ~= nil then 
        return cfg.WardrobeMainTab, cfg.WardrobeTab 
    end
    return 1, 10
end

local function getItemTypes(resId)
    local cfg = getItemConfig(resId)
    return (cfg and cfg.ItemType) or 5, (cfg and cfg.ItemSubType) or 0
end

local function buildFakeItemData(resId)
    resId = tonumber(resId)
    if not resId or resId == 0 then return nil end

    local ok, result = pcall(function()
        local cfg = getItemConfig(resId)
        local itemType, itemSubType = (cfg and cfg.ItemType) or 5, (cfg and cfg.ItemSubType) or 0
        local mainTab, subTab = getItemTabs(resId)
        local fakeId = fakeInstanceId(resId)

        return {
            insID = tostring(fakeId),
            ins_id = fakeId,
            resID = resId,
            res_id = resId,
            item_res_id = resId,
            itemType = itemType,
            itemSubType = itemSubType,
            mainTabType = mainTab,
            subTabType = subTab,
            count = 1,
            expireTS = 0,
            validHours = 0,
            isNew = false,
            itemQuality = (cfg and cfg.ItemQuality) or 0,
            colorID = 0,
            patternID = 0,
            expire_time = 0,
            obtain_time = 0
        }
    end)
    return ok and result or nil
end

local function isWorn(insId)
    if not DataMgr or type(DataMgr.rolewear) ~= "table" then return false end
    local strId = tostring(insId)
    for _, v in pairs(DataMgr.rolewear) do 
        if tostring(v) == strId then return true end 
    end
    return false
end

local function mergeCustomWornToRolewear()
    if not DataMgr or type(DataMgr.rolewear) ~= "table" then return end
    for resId, _ in pairs(LSI.customWorn) do
        if isCustomItem(resId) then
            local fakeId = tostring(fakeInstanceId(resId))
            local found = false
            for _, v in pairs(DataMgr.rolewear) do 
                if tostring(v) == fakeId then 
                    found = true 
                    break 
                end 
            end
            if not found then
                table.insert(DataMgr.rolewear, fakeId)
            end
        end
    end
end

local function setWornState(resId, worn)
    resId = tonumber(resId)
    if not resId then return end

    if worn then
        local fakeData = buildFakeItemData(resId)
        if fakeData and fakeData.itemSubType then
            local subType = fakeData.itemSubType
            for rid, _ in pairs(LSI.customWorn) do
                local fr = buildFakeItemData(rid)
                if fr and fr.itemSubType == subType then
                    LSI.customWorn[rid] = nil
                end
            end
            LSI.customWorn[resId] = true

            if DataMgr and type(DataMgr.UpdateRoleWearData) == "function" then
                pcall(DataMgr.UpdateRoleWearData, tostring(fakeInstanceId(resId)), "")
            else
                mergeCustomWornToRolewear()
            end
        end
    else
        LSI.customWorn[resId] = nil
        if DataMgr and type(DataMgr.UpdateRoleWearData) == "function" then
            pcall(DataMgr.UpdateRoleWearData, "", tostring(fakeInstanceId(resId)))
        end
    end
end

function _G.AddCustomSkinItem(resId)
    resId = tonumber(resId)
    if not resId or resId == 0 then return false end
    if LSI.customSet and LSI.customSet[resId] then return true end

    for _, id in ipairs(CUSTOM_ITEM_IDS) do 
        if id == resId then return true end 
    end
    CUSTOM_ITEM_IDS[#CUSTOM_ITEM_IDS + 1] = resId
    if LSI.customSet then LSI.customSet[resId] = true end
    return true
end

function _G.RemoveCustomSkinItem(resId)
    resId = tonumber(resId)
    for i = #CUSTOM_ITEM_IDS, 1, -1 do
        if CUSTOM_ITEM_IDS[i] == resId then
            table.remove(CUSTOM_ITEM_IDS, i)
            LSI.fakeByRes[resId] = nil
            if LSI.customSet then LSI.customSet[resId] = nil end
            return true
        end
    end
    return false
end

local function safeRequire(paths)
    for _, p in ipairs(paths) do 
        local ok, mod = pcall(require, p)
        if ok and mod and type(mod) == "table" then 
            return mod 
        end 
    end
    return nil
end

local function hookValidTime()
    if LSI.validTimeHooked then return true end
    if not DataMgr or not DataMgr.IsValidTime then return false end

    local original = DataMgr.IsValidTime
    DataMgr.IsValidTime = function(ts)
        if ts == nil or tonumber(ts) == 0 then 
            return true 
        end
        return original(ts)
    end

    LSI.validTimeHooked = true
    return true
end

function _G.InjectLobbySkins()
    if LSI.applied then return true end

    hookValidTime()

    if not LSI.validTimeHooked and not LSI.validTimeTimer then
        LSI.validTimeTimer = true
        local ticker = _G.Mytimer_ticker or (_G.timer_ticker)
        if ticker and ticker.AddTimerLoop then
            ticker.AddTimerLoop(1, function() 
                if not LSI.validTimeHooked then hookValidTime() end
            end, 5, 1)
        end
    end

    local ArmoryHandler = safeRequire({ "client.network.Protocol.ArmoryHandler", "Client.network.Protocol.ArmoryHandler" })
    if ArmoryHandler then
        local ArmorySystem = safeRequire({ "client.logic.armory.logic_armory", "Client.logic.armory.logic_armory" })
        if ArmorySystem then
            if ArmoryHandler.send_install_weapon_skin then
                local original = ArmoryHandler.send_install_weapon_skin
                ArmoryHandler.send_install_weapon_skin = function(client_data, weapon_id, instanceID)
                    if isFakeInstance(instanceID) then
                        ArmorySystem.install_weapon_skin_rsp(client_data, 0, weapon_id, tonumber(instanceID))
                        return
                    end
                    return original(client_data, weapon_id, instanceID)
                end
            end
            if ArmoryHandler.send_uninstall_weapon_skin then
                local original = ArmoryHandler.send_uninstall_weapon_skin
                ArmoryHandler.send_uninstall_weapon_skin = function(client_data, weapon_id)
                    local cur = ArmorySystem.rsp_list and ArmorySystem.rsp_list.install_list and ArmorySystem.rsp_list.install_list[weapon_id]
                    local skinId = cur and cur.skin_id
                    if skinId and isFakeInstance(skinId) then
                        ArmorySystem.uninstall_weapon_skin_rsp(client_data, 0, weapon_id)
                        return
                    end
                    return original(client_data, weapon_id)
                end
            end
        end
    end

    local WardrobeData = safeRequire({ 
        "client.slua.logic.wardrobe.wardrobe_data", 
        "client.slua.logic.wardrobe.WardrobeData", 
        "Client.slua.logic.wardrobe.wardrobe_data" 
    })

    if WardrobeData then

        local function hookByResId(original, self, id)
            if isCustomItem(id) then 
                local fakeData = buildFakeItemData(id)
                if fakeData then return fakeData end
            end
            return original(self, id)
        end

        local function hookByInsId(original, self, id)
            local realId = isFakeInstance(id)
            if realId then 
                local fakeData = buildFakeItemData(realId)
                if fakeData then return fakeData end
            end
            return original(self, id)
        end

        for _, name in ipairs({ "GetHallDepotItemDataByResIDAndValidExpireTime", "GetHallDepotItemDataByResID" }) do
            if WardrobeData[name] then 
                local original = WardrobeData[name]
                WardrobeData[name] = function(self, id) return hookByResId(original, self, id) end
            end
        end

        for _, name in ipairs({ "GetHallDepotItemDataByInsID", "GetValidHallDepotItemDataByInsID" }) do
            if WardrobeData[name] then 
                local original = WardrobeData[name]
                WardrobeData[name] = function(self, id) return hookByInsId(original, self, id) end
            end
        end

        if WardrobeData.GetArrayHallDepotItemInfo then
            local original = WardrobeData.GetArrayHallDepotItemInfo
            local maxAdd = LSI.MAX_CUSTOM_IN_LIST
            WardrobeData.GetArrayHallDepotItemInfo = function(self)
                local list = original(self) or {}
                if maxAdd == 0 then return list end

                local seenRes, seenIns = {}, {}
                for _, v in pairs(list) do
                    if v and type(v) == "table" then
                        local resId = v.resID or v.res_id or v.item_res_id
                        local insId = v.insID or v.ins_id
                        if resId then seenRes[tonumber(resId)] = true end
                        if insId then seenIns[tostring(insId)] = true end
                    end
                end

                local added = 0
                for i = 1, #CUSTOM_ITEM_IDS do
                    if added >= maxAdd then break end
                    local resId = CUSTOM_ITEM_IDS[i]
                    if type(resId) ~= "number" then resId = tonumber(resId) end
                    if resId and resId ~= 0 then
                        local fakeId = fakeInstanceId(resId)
                        if not seenRes[resId] and not seenIns[tostring(fakeId)] then
                            local fakeData = buildFakeItemData(resId)
                            if fakeData and type(fakeData) == "table" then
                                table.insert(list, fakeData)
                                seenRes[resId] = true
                                seenIns[tostring(fakeId)] = true
                                added = added + 1
                            end
                        end
                    end
                end
                return list
            end
        end

        for _, name in ipairs({ "GetHallDepotItemCountByResIDAndValidInfo", "GetHallDepotItemCountByResID" }) do
            if WardrobeData[name] then 
                local original = WardrobeData[name]
                WardrobeData[name] = function(self, resId, ...)
                    return isCustomItem(resId) and 1 or original(self, resId, ...)
                end
            end
        end

        for _, name in ipairs({ "HasItem", "HasValidItem" }) do
            if WardrobeData[name] then 
                local original = WardrobeData[name]
                WardrobeData[name] = function(self, id, ...)
                    return (isCustomItem(id) or isFakeInstance(id)) and true or original(self, id, ...)
                end
            end
        end
    end

    local WardRobeHandler = safeRequire({ "client.network.Protocol.WardRobeHandler", "Client.network.Protocol.WardRobeHandler" })
    if WardRobeHandler then
        local OK_CODE = (type(NetErrorCode_NONE) == "string" and NetErrorCode_NONE) or "ok"

        if WardRobeHandler.send_depot_put_on_req then
            local original = WardRobeHandler.send_depot_put_on_req
            WardRobeHandler.send_depot_put_on_req = function(insId)
                local realId = isFakeInstance(insId)
                if realId then
                    insId = tonumber(insId)
                    if isWorn(insId) then
                        if WardRobeHandler.on_depot_put_down_rsp then 
                            WardRobeHandler.on_depot_put_down_rsp(OK_CODE, { res_id = realId, instid = insId }, insId)
                            setWornState(realId, false)
                        end
                        return
                    end
                    local fakeData = buildFakeItemData(realId)
                    if fakeData then
                        local item = { 
                            res_id = realId, 
                            instid = insId, 
                            color = fakeData.colorID or 0, 
                            pattern = fakeData.patternID or 0,
                            color_id = fakeData.colorID or 0, 
                            pattern_id = fakeData.patternID or 0 
                        }
                        if WardRobeHandler.on_depot_put_on_rsp then 
                            WardRobeHandler.on_depot_put_on_rsp(OK_CODE, item, nil, nil, insId, nil)
                            setWornState(realId, true)
                        end
                    end
                    return
                end
                return original(insId)
            end
        end

        if WardRobeHandler.send_depot_put_down_req then
            local original = WardRobeHandler.send_depot_put_down_req
            WardRobeHandler.send_depot_put_down_req = function(insId)
                local realId = isFakeInstance(insId)
                if realId then
                    if WardRobeHandler.on_depot_put_down_rsp then 
                        WardRobeHandler.on_depot_put_down_rsp(OK_CODE, { res_id = realId, instid = tonumber(insId) }, insId)
                        setWornState(realId, false)
                    end
                    return
                end
                return original(insId)
            end
        end
    end

    local AvatarLogic = safeRequire({ "client.slua.logic.wardrobe.logic_wardrobe_avatar", "Client.slua.logic.wardrobe.logic_wardrobe_avatar" })
    if AvatarLogic and AvatarLogic.InitCurrentWearPreviewMap then
        local original = AvatarLogic.InitCurrentWearPreviewMap
        AvatarLogic.InitCurrentWearPreviewMap = function(self, force)
            original(self, force)
            for resId, _ in pairs(LSI.customWorn) do
                if isCustomItem(resId) then
                    local fakeData = buildFakeItemData(resId)
                    if fakeData and fakeData.itemSubType and AvatarLogic.AddToWearInfo then
                        AvatarLogic:AddToWearInfo(fakeData.itemSubType, tostring(fakeInstanceId(resId)), resId, fakeData.colorID or 0, fakeData.patternID or 0)
                    end
                end
            end
        end
    end

    LSI.customSet = {}
    for _, id in ipairs(CUSTOM_ITEM_IDS) do
        if type(id) == "number" and id ~= 0 then
            LSI.customSet[id] = true
        end
    end

    mergeCustomWornToRolewear()

    local fashionbagData = safeRequire({ "client.slua.logic.wardrobe.fashionbag.fashionbag_data", "Client.slua.logic.wardrobe.fashionbag.fashionbag_data" })
    if fashionbagData and fashionbagData.OnSelectFashionBag then
        local original = fashionbagData.OnSelectFashionBag
        fashionbagData.OnSelectFashionBag = function(self, index)
            if type(original) == "function" then original(self, index) end
            pcall(mergeCustomWornToRolewear)
        end
    end

    local AvatarDataUtil = safeRequire({ "GameLua.Mod.Library.GamePlay.Avatar.AvatarDataUtil", "client.logic.avatar.AvatarDataUtil" })
    if AvatarDataUtil and AvatarDataUtil.GetAvatarStandaloneData then
        local original = AvatarDataUtil.GetAvatarStandaloneData
        if type(original) == "function" then
            AvatarDataUtil.GetAvatarStandaloneData = function()
                local info, hasData = original()
                if type(info) == "table" and type(info.wear_ext) == "table" then
                    for resId, _ in pairs(LSI.customWorn) do
                        if isCustomItem(resId) then
                            local fakeData = buildFakeItemData(resId)
                            if fakeData and (fakeData.resID or fakeData.res_id) then
                                local rid = fakeData.resID or fakeData.res_id
                                table.insert(info.wear_ext, { rid, fakeData.colorID or 0, fakeData.patternID or 0 })
                                hasData = true
                            end
                        end
                    end
                end
                return info, hasData
            end
        end
    end

    LSI.applied = true
    return true
end

pcall(function()
    _G.InjectLobbySkins()

    if _G.Mytimer_ticker then
        _G.Mytimer_ticker.AddTimerLoop(2, function()
            pcall(function()
                if _G.LobbySkinInjector and _G.LobbySkinInjector.customWorn then
                    if DataMgr and type(DataMgr.rolewear) == "table" then
                        for resId, _ in pairs(_G.LobbySkinInjector.customWorn) do
                            local fakeId = 900000000 + tonumber(resId)
                            local found = false
                            for _, v in pairs(DataMgr.rolewear) do
                                if tostring(v) == tostring(fakeId) then found = true break end
                            end
                            if not found then
                                table.insert(DataMgr.rolewear, tostring(fakeId))
                            end
                        end
                    end
                end
            end)
        end, -1, 1)
    end
end)
